/**
 * stdlib-md-shim — the scrml:md runtime shim IS the scrml reader (SPEC §67.8, change-id
 * s462-md-phase1; ruling S462 F4: "one md reader, written in scrml (`scrml:md`), used by BOTH
 * compilers").
 *
 * Every other stdlib shim is hand-written JS mirroring a `.scrml` export list. A hand-written md
 * shim would be a second markdown reader, so compiler/runtime/stdlib/md.js is GENERATED by
 * scripts/gen-md-shim.ts: impl#1's library-mode compile of stdlib/md/index.scrml with the
 * host-global alias import inlined. This file pins that:
 *
 *   §1  the shim says it is generated and stamps the sha-256 of the CURRENT scrml source — an edit
 *       to the reader that is not regenerated fails here;
 *   §2  the shim is the compile plus nothing hand-added: it has no `import` (it is copied alone into
 *       a program's `_scrml/`), and every top-level function it declares is one the source declares;
 *   §3  BEHAVIOURAL PARITY: a fresh library-mode compile of the scrml source, loaded as a module,
 *       returns the same tree and diagnostics as the committed shim over a corpus that touches every
 *       construct, every OUT construct and the limits.
 *
 * (The byte-for-byte `bun scripts/gen-md-shim.ts --check` is the stricter gate; it is not run here
 * because an unrelated codegen change that alters emitted text but not behaviour should not turn the
 * pre-commit suite red. §3 catches any change that alters behaviour.)
 */

import { describe, test, expect, beforeAll } from "bun:test";
import { readFileSync, mkdtempSync, rmSync, writeFileSync } from "fs";
import { join } from "path";
import { tmpdir } from "os";
import { compileReader, sourceHash, MD_SHIM, MD_SOURCE } from "../../../scripts/gen-md-shim.ts";
import * as shim from "../../runtime/stdlib/md.js";

const shimText = readFileSync(MD_SHIM, "utf8").replace(/\r\n/g, "\n");

const CORPUS = [
  "# Title\n\nSome *em*, **strong**, `code`, ~~del~~ and a [link](/u \"t\").",
  "- one\n- two\n  - nested\n\n1. first\n2. second\n\n> quoted\n\n---",
  "```js\nlet x = 1\n```\n\n| a | b |\n| :- | -: |\n| 1 | 2 |\n\n![img](/i.png)\nline\\\nbreak",
  "a <b>x</b> &amp; <https://x.y> [a][b] [^1] _u_ ~s~ \n* i\n1) i\n***\n~~~\n## t ##\n[a](b 'c') [a](<b>)",
  "Title\n===\n\nTitle\n---\n\n    indented\n\n- [ ] task\n\n> a\nlazy\n\na | b\n--- | ---",
  "*foo**bar**baz* **foo* *(*foo*)* [link [foo [bar]]](/uri) [foo [bar](/a)](/b) *[foo*](/uri)",
  ">".repeat(60) + " deep\n\n" + "*a ".repeat(50) + "b" + " a*".repeat(50) + "\n\n" + "[".repeat(40) + "x",
  "[a](x".repeat(400),
  "a\u0000b\r\nc",
  "",
];

let fresh;

beforeAll(async () => {
  const dir = mkdtempSync(join(tmpdir(), "scrml-md-fresh-"));
  const compiled = compileReader();
  // the compiled module imports its host-global alias from ./_scrml/_global.js
  const { mkdirSync } = await import("fs");
  mkdirSync(join(dir, "_scrml"), { recursive: true });
  writeFileSync(join(dir, "_scrml", "_global.js"), "export default globalThis;\n");
  writeFileSync(join(dir, "index.js"), compiled);
  fresh = await import(join(dir, "index.js"));
  rmSync(dir, { recursive: true, force: true });
});

describe("scrml:md shim — generated from the scrml reader", () => {
  test("§1 the shim is marked generated and stamps the current source hash", () => {
    expect(shimText.startsWith("// scrml:md — runtime shim. GENERATED — do not edit.\n")).toBe(true);
    const m = /^\/\/ source-sha256: ([0-9a-f]{64})$/m.exec(shimText);
    expect(m && m[1]).toBe(sourceHash());
  });

  test("§2 the shim imports nothing and declares only functions the scrml source declares", () => {
    expect(/^\s*import\s/m.test(shimText)).toBe(false);
    const src = readFileSync(MD_SOURCE, "utf8");
    const declared = new Set([...src.matchAll(/^\s*(?:export\s+)?fn\s+([A-Za-z_]\w*)/gm)].map((m) => m[1]));
    const emitted = [...shimText.matchAll(/^(?:export\s+)?function\s+([A-Za-z_$][\w$]*)/gm)].map((m) => m[1])
      .filter((n) => !n.startsWith("_scrml_"));
    expect(emitted.filter((n) => !declared.has(n))).toEqual([]);
  });

  test("§3 a fresh compile of the scrml source and the committed shim read every corpus input identically", () => {
    expect(typeof fresh.parse).toBe("function");
    for (const src of CORPUS) {
      expect(JSON.stringify(fresh.parse(src))).toBe(JSON.stringify(shim.parse(src)));
    }
    const body = "\n        ## A\n\n        b\n    ";
    expect(fresh.dedent(body)).toEqual(shim.dedent(body));
    const doc = shim.parse("# A\n# A\n> # b");
    expect(fresh.headingSlugs(doc, ["a"])).toEqual(shim.headingSlugs(doc, ["a"]));
  });
});
